test_patch:
diff --git a/rust/fslc/tests/reviewgraphen_generated_calibration_13.rs b/rust/fslc/tests/reviewgraphen_generated_calibration_13.rs
new file mode 100644
--- /dev/null
+++ b/rust/fslc/tests/reviewgraphen_generated_calibration_13.rs
@@ -0,0 +1,38 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use std::process::Command;
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let path = std::env::temp_dir().join(format!(
+        "reviewgraphen-calibration-13-{}.fsl",
+        std::process::id()
+    ));
+    std::fs::write(
+        &path,
+        r#"
+observed_property Drift {
+  target "{"
+  source "metrics.jsonl"
+  window "7d"
+  require percentile(metric.latency) <= 0.9
+}
+"#,
+    )
+    .expect("write project");
+
+    let output = Command::new(env!("CARGO_BIN_EXE_fslc"))
+        .args(["check", path.to_str().expect("UTF-8 path")])
+        .output()
+        .expect("run fslc check");
+    std::fs::remove_file(&path).expect("remove project");
+
+    assert_eq!(output.status.code(), Some(2));
+    assert!(output.stderr.is_empty());
+    let value: serde_json::Value =
+        serde_json::from_slice(&output.stdout).expect("JSON output");
+    assert_eq!(value["result"], "error");
+    assert_eq!(value["kind"], "parse");
+    assert!(
+        value["message"]
+            .as_str()
+            .is_some_and(|message| message.contains("percentile(metric.latency) <= 0.9"))
+    );
+}
